namespace PsychologyApp.Application.Articles;

public static partial class ArticleContent
{
    private static readonly Article[] AdditionalArticlesZh =
    [
        MiniArticle(ArticleIds.CallNerves, "打电话前紧张", "让第一通电话更简单", "不用排练整段对话。写下一个目标和开场句。通话时可以看笔记、请对方重复，或暂停一下。打出电话本身就是一次成功，不必追求说得完美。"),
        MiniArticle(ArticleIds.WaitingForReply, "等待回复时", "聊天中的沉默并不能说明原因", "写下三种可能的原因，其中包括一种中性的解释，再决定什么时候查看。如果事情紧急，就想好何时联系谁，而不是反复刷新屏幕。"),
        MiniArticle(ArticleIds.AfterSocialEvent, "聚会后，别反复琢磨每句话", "打断脑海中的对话回放", "想起一个进展还不错的时刻，再指出一个目前无法下结论的地方。不要事后寻找完美的说法。回到眼前的事情；重要的话题可以以后再谈。"),
        MiniArticle(ArticleIds.FearOfMistakes, "犯错不等于被定性", "明确什么叫做够好", "开始前，先决定什么结果就够了，并检查一项重要要求。如果出了错，了解实际影响和下一个可修正的步骤。一次失误不能代表完整的你。"),
        MiniArticle(ArticleIds.ChangeAnxiety, "变化让人担心时", "把事实和未知分开", "分成两栏：已经知道的，以及还可以查清的。选一个问题，并定下之后再看的时间。其余可以先放一放；不确定不等于坏结果。"),
        MiniArticle(ArticleIds.WorryBeforeTask, "开始一件难事之前", "不必等到完全有把握才开始", "想清楚安全开始需要什么：材料、十分钟，或一个说明。先只做这一部分，再决定是否继续。无需等焦虑消失。"),
        MiniArticle(ArticleIds.AvoidedFirstStep, "只迈出第一步", "开始可以只花两分钟", "把开始变得很小：打开文件、写个标题或拿出材料。之后你可以停下。目标是让起步容易些，不是剥夺你休息的权利。"),
        MiniArticle(ArticleIds.CheckingLoop, "检查之后就停下", "检查前先设好次数", "先决定要检查什么、检查几次。最后一次完成后做个标记，然后切换到别的事情。如果焦虑要求再查一次，把它看作焦虑的请求，而不是新证据。"),
        MiniArticle(ArticleIds.PublicPlaceAnxiety, "在公共场所感到焦虑", "找到支点，也保留选择", "感受脚下的支撑，说出周围几个物品。找一个能安静站一会儿的地方。如果不安全，你可以离开或求助；练习不该让你被迫留在那里。"),
        MiniArticle(ArticleIds.MorningWorry, "早晨不必列出所有担忧", "不用早餐前解决整周的问题", "写下担忧，并圈出今天确实需要处理的一件事。其他问题可以安排时间再看，或等有新信息再说。先迈出一步，而不是试图预料一切。"),
        MiniArticle(ArticleIds.SensoryOverload, "声音和事情太多时", "减轻注意力的负担", "如果可以，移开一个噪声来源、调暗屏幕，或去安静些的地方。选一个注意力支点。暂停一下不代表必须立刻回到原来的节奏。"),
        MiniArticle(ArticleIds.EveningTension, "温和地结束一天", "把没完成的事留到明天", "花几分钟记下已完成的事、可以延期的事，以及明天从哪里开始。如果作息被打乱，选一个简单的睡前提示，而不是严格又容易中断的仪式。"),
        MiniArticle(ArticleIds.AnxietyComedown, "焦虑高峰之后", "先恢复，再回顾", "确认自己现在安全，给自己一点时间回到平常节奏。熟悉而简单的事情可能有帮助。之后记下什么支持了你，以及有什么想和专业人士讨论。"),
        MiniArticle(ArticleIds.SafePractice, "练习不是考试", "按自己的情况调整练习", "可以缩短练习、睁着眼睛、跳过步骤或停下来。如果感到不舒服，就自然呼吸，并换一个支点。不必为了遵守说明而忍受不适。"),

        MiniArticle(ArticleIds.ThoughtLabel, "给想法起个名字", "看见它，不必和它争辩", "试着说：「我注意到自己有这样的想法……」。这并不能证明想法是错的，但能帮助你把它看作一个想法。然后问问自己，现在什么小行动符合任务或价值观。"),
        MiniArticle(ArticleIds.MindReading, "别猜别人心里怎么想", "把观察和推测分开", "写下对方实际说了什么、做了什么，再写下你的解读。如果答案很重要，可以平静地问清楚；如果不重要，就先留着疑问，别把猜测当事实。"),
        MiniArticle(ArticleIds.WorstVsLikely, "最坏结果不等于最可能的结果", "给其他可能性留些空间", "写下最坏、最好和最可能的结果。为最可能的情况做准备；只有确实需要时，再为最坏情况想一个合理的安全方案。别把精力都花在想象中的每种情境上。"),
        MiniArticle(ArticleIds.EvidenceAndUnknown, "我知道什么，还有什么不知道", "别用焦虑的猜测填补空白", "分成两栏：「我知道」和「我还不知道」。针对未知，选择获取信息的方式或下次查看的时间。如果现在查不到，就先让问题保持开放。"),
        MiniArticle(ArticleIds.NegativityFilter, "也看看做得好的部分", "为整体图景补充一个事实", "遇到困难后，大脑容易盯着错误，忽略普通或顺利的时刻。说出一个不符合负面判断的事实。不必假装一切都好，只要看见完整图景。"),
        MiniArticle(ArticleIds.ConversationReplay, "别没完没了地回放对话", "判断是否有下一步", "问问自己有没有一个可以修正的具体问题。如果有，写下一个简短的下一步；如果没有，就认出这是反复回想，然后回到现在看到、听到或正在做的事。"),
        MiniArticle(ArticleIds.DecisionFatigue, "简化一个小选择", "提前决定什么就够了", "面对重复的小选择，可以用一条简单规则：预算、时间或一个质量标准。按规则做，不必永远比较所有选项。重要决定则另留时间收集信息。"),
        MiniArticle(ArticleIds.GoodEnough, "够好也是一种成果", "限制不必要的修改", "定下两个必须满足的要求和停止时间。达到后就保存或发送。只有出现具体问题才继续修改，不必追求不可能的完美。"),
        MiniArticle(ArticleIds.ControlInfluence, "我能影响什么，不能影响什么", "专注于眼下做得到的行动", "画两个圈：哪些事由你决定，哪些不由你决定。先在第一个圈里选一步；对于第二个圈，考虑边界、支持或如何面对不确定。这不会抹去现实中的不公和限制。"),
        MiniArticle(ArticleIds.SelfTalkReset, "换一种对自己说话的语气", "尊重自己，也说得具体", "把「我又把一切搞砸了」换成行动描述：「我错过了期限，接下来问问还能补救什么。」这不是为错误开脱，而是让你不必靠羞辱自己来继续前进。"),
        MiniArticle(ArticleIds.WorryAboutWorry, "因为自己焦虑而再次焦虑", "别要求自己立刻平静下来", "当你想「我不应该这样」时，把它认作第二层焦虑。允许第一层反应存在，再回到最近的一件事。如果焦虑常常影响生活，可以找专业人士聊聊。"),
        MiniArticle(ArticleIds.CompareHighlightReel, "别拿自己的生活和别人的展示面比较", "动态只展示选中的片段，不是完整生活", "提醒自己，一条动态只是片段。如果比较让心情变差，暂停浏览，换成自己的参照：什么对你重要，而不是看起来多么耀眼。"),
        MiniArticle(ArticleIds.IntrusiveThoughts, "不想要的想法不等于意图", "关注行为和情境，而不是只盯着想法", "令人不安的想法可能正因为违背你的愿望而让你害怕。无需反复测试自己。注意到它，然后回到选择的事情；如果它严重影响生活，可以寻求专业支持。"),
        MiniArticle(ArticleIds.OneThingAtATime, "一次只做一件事", "减少切换任务的消耗", "写下所有需要关注的事，再选一件先做一小段时间。如果可以，关掉多余标签页或通知。其他任务没有消失，只是在列表里等着。"),

        MiniArticle(ArticleIds.MoodMovement, "精力不足时，稍微动一动", "行动不必等心情变好才开始", "选一个能做到的动作，做几分钟：伸展、在房间里走走，或看看窗外。之后留意自己的感受。这是一次尝试，不是必须锻炼或必须感觉更好。"),
        MiniArticle(ArticleIds.PleasureMastery, "愉快感和完成感", "留意不同类型的支持性活动", "可以安排一件愉快的事和一件带来完成感的小任务，也可以是同一件事。没做到时，这说明当前负担如何，不是责怪自己的理由。"),
        MiniArticle(ArticleIds.EnergyBudget, "分配精力，而不只是时间", "为恢复留出空间", "标出一天中最耗精力的事情。如果可能，在它们之间安排短暂休息或轻松一点的任务。有余地的安排，往往比没有停顿的日程更实际。"),
        MiniArticle(ArticleIds.RestBreak, "休息时不必内疚", "休息能帮助你做下一个选择", "选一段短暂停歇，再决定什么对你有帮助：安静、喝水、伸展或望向远处。别把暂停变成另一项任务。如果负担不允许休息，问题不只是自律。"),
        MiniArticle(ArticleIds.StartFriction, "开始前移开一个障碍", "提前准备好起点", "留意什么常让你难以开始：找文件、步骤太多，或任务不清楚。只准备下一步：打开文档、摆好材料或写下第一个问题。无需一次安排好全部流程。"),
        MiniArticle(ArticleIds.TransitionRitual, "在任务之间切换", "短暂停顿能让下一步更清楚", "开始新任务前停一分钟：关掉前一个文件，记下未完成部分，并说出接下来要做什么。这不是必须遵守的仪式，也不是拼命提高效率，只是一个清晰的过渡。"),
        MiniArticle(ArticleIds.TaskActivation, "难以开始时", "行动可能先于动力", "选一件五分钟内能完成、看得见的动作；计时器只有在有帮助时才用。结束后再决定是否继续。动力可能在开始后出现，但不必强迫自己。"),
        MiniArticle(ArticleIds.GentleRoutine, "灵活的日常，而非完美作息", "在一天中保留一个稳定的锚点", "选一个容易重复的小提示，比如早餐后做计划。时间变了，就保留顺序而不是精确到分钟。漏掉一天，不妨碍之后再回来。"),
        MiniArticle(ArticleIds.WakeAtNight, "夜里醒来时", "让环境保持安静，尽量别看时间", "试着别按分钟评判这一夜。如果躺着很难受，可以在昏暗灯光下短暂做点安静的事，困了再回去。睡眠困难持续时，请和医疗专业人士讨论。"),
        MiniArticle(ArticleIds.SmallDayPlan, "给一天留出余地", "选好重点，也为意外留空间", "写下一件重要任务、一件小事和一次休息。其余都可以视时间和精力决定。计划可以调整；灵活不代表辜负自己。"),
        MiniArticle(ArticleIds.AskForHelpTask, "请别人帮一个具体部分", "清楚的请求减少猜测", "不要只说「帮帮我」，可以说行动和期限：「今天能帮我看一下这段吗？」再说明怎样的结果有用。这样对方更容易回答，你也更容易判断是否合适。"),
        MiniArticle(ArticleIds.MeaningfulActivity, "做一件对自己有意义的事", "把小行动和自己的价值连起来", "问问自己，这件事里什么最重要：关心、好奇、可靠或休息。选一个朝这个方向的小行动。即使不能马上改变整体情况，它也可以有意义。"),
        MiniArticle(ArticleIds.FlexibleGoals, "调整计划，但不必放弃目标", "让今天的步骤匹配今天的精力", "如果原计划太大，就缩小任务或改变方法。保留方向，不一定保留形式：做十分钟而非一小时，先写草稿而非追求完美。目标可以灵活，不必变成惩罚。"),
        MiniArticle(ArticleIds.CelebrateCompletion, "留意自己已经完成的事", "大脑常常马上跳到下一项任务", "完成后，简单说出自己做了什么、付出了什么努力。不必安排奖励，注意到事实就够了。这样你也能看见已经完成的，而不只是待办事项。"),

        MiniArticle(ArticleIds.NameEmotion, "更准确地说出感受", "一个词能帮助你选择回应", "不妨把「我不好受」换成更具体的词：紧张、失望、害怕或疲惫。不确定也没关系，这不是测试。接着问自己现在需要什么：安全、暂停、清晰或联系。"),
        MiniArticle(ArticleIds.MixedFeelings, "两种不同感受可以同时存在", "矛盾的感受不代表你不一致", "你可以为变化感到高兴，也怀念以前的生活。说出两面，不必立刻选一个。问问哪种感受现在更需要关注，再给它一点照顾。"),
        MiniArticle(ArticleIds.AngerPause, "生气时先暂停再回应", "先确保安全，再选择说什么", "如果谈话越来越激烈，可以提出暂停并说好何时再谈。先去安全的地方，给自己一些时间。如果有暴力风险，请寻找安全处和帮助。"),
        MiniArticle(ArticleIds.ShameKindness, "回应羞耻感，而不是羞辱自己", "可以修正错误，不必惩罚自己", "对自己说：「我现在觉得羞耻，但这份感受不能概括我。」把行为和身份分开：发生了什么，能修正什么？选一种你会给亲近之人的回应。"),
        MiniArticle(ArticleIds.GuiltRepair, "内疚：补救，或慢慢放下", "分清承担责任和无休止自责", "如果你伤害了别人，想一想具体的补救和真诚道歉。如果没有真正越界，内疚可能只是一种感受，不是证据。无论哪种情况，不停惩罚自己都帮不了受伤的人。"),
        MiniArticle(ArticleIds.EnvyInformation, "嫉妒可能提示你真正想要什么", "把比较变成自己的方向", "问问自己羡慕的是什么：自由、认可、亲近或能力？这不代表你是坏人。朝自己的需要迈出一小步，不必照搬别人的生活或否定自己的路。"),
        MiniArticle(ArticleIds.AllowSadness, "悲伤不必马上消失", "给感受一点空间，再选择支持", "说出失去或失望，不必逼自己振作。问问现在什么更温和：独处、给亲近的人发消息，或完成一件必要的小事。如果长期影响生活，可以寻求帮助。"),
        MiniArticle(ArticleIds.Numbness, "难以感受到什么时", "别逼自己一下子敞开心扉", "麻木可能是面对过载的一种反应，但它本身不能说明原因。从中性的事开始：你在哪里、看见什么、十分钟后想做什么。如果这让你担心或持续存在，可以和专业人士谈谈。"),
        MiniArticle(ArticleIds.EmotionWave, "感受会变化，即使不是立刻", "观察它，不用计时", "给感受从零到十打个分，并用一个词命名。过一会儿可以再看，不必要求分数下降。目标是发现变化并保留选择，而不是测量自己多久能平静。"),
        MiniArticle(ArticleIds.BodyNoticingChoice, "按舒服的节奏感受身体", "也可以选一个外部支点", "如果留意身体感受让你不舒服，不必勉强。看看稳定的物体、感受椅子的支撑，或说出周围的声音。关注身体是一种选择，不是自助的必要条件。"),
        MiniArticle(ArticleIds.PauseBeforeReact, "在冲动和行动之间暂停", "选择一个不那么容易后悔的回应", "如果想立刻发消息，在安全的前提下等几分钟。说清消息的目的，只留下必要的话。如果等待会带来伤害，就采取行动；暂停应该有帮助，而不是添堵。"),
        MiniArticle(ArticleIds.EmotionalBoundary, "别人的感受不需要由你来修好", "可以关心对方，也保留自己的界限", "你可以倾听，不必什么都答应或承诺解决问题。问问对方需要陪伴还是建议，再说清自己能提供什么。关心别人不等于放弃自己的需要。"),
        MiniArticle(ArticleIds.FeelingNotAction, "有感受不等于必须行动", "情绪和行为之间还有选择", "你可以生气但不辱骂，害怕时提出暂停，或嫉妒时不查对方消息。说出冲动，再选择一个既考虑感受也顾及他人安全的行动。"),
        MiniArticle(ArticleIds.AfterCrying, "哭过之后", "照顾好接下来的一分钟", "可以洗脸、安静坐一会儿、正常呼吸、要杯水或联系亲近的人。不必马上解释为什么哭。如果你身处危险或无法确保安全，请尽快求助。"),

        MiniArticle(ArticleIds.SpecificRequest, "提出具体请求", "清楚的请求给对方留下回应空间", "说清发生了什么、需要什么、希望何时完成。例如：「我来不及准备材料，你能在周五前帮我处理这一部分吗？」对方可以拒绝，你也可以再找别的办法。"),
        MiniArticle(ArticleIds.ListenReflect, "先理解，再回应", "简单确认能缓和紧张", "用自己的话复述听到的内容，并问问理解得是否准确。对方没问时，先别给建议。即使不同意，也可以让对方知道你听懂了。"),
        MiniArticle(ArticleIds.BoundarySentence, "表达界限的一句话", "简短回应往往比长篇辩解更清楚", "试试：「我现在接不了这件事」或「这种语气让我不舒服，我们平静下来再谈」。按处境和安全调整说法。界限说明你会怎么做，不是控制别人必须怎么做。"),
        MiniArticle(ArticleIds.NoWithoutEssay, "可以拒绝，不必长篇解释", "选择礼貌而清楚的说法", "可以说「谢谢，但我做不到」或「这不适合我」。只有你愿意时才提供替代方案。在不安全的情况下，直接拒绝未必最合适；优先选择保护自己的做法。"),
        MiniArticle(ArticleIds.DifficultTalkOpening, "带着目标开始一场难谈的话", "只谈一件事和一个请求", "选一个平静的时刻，说清具体情况和希望改变什么。例如：「计划突然变化让我很难安排，我们能不能早点互相通知？」如果这样做不安全，就不要开始谈。"),
        MiniArticle(ArticleIds.RepairAfterConflict, "争执后重新开始对话", "先迈出一个澄清的小步骤", "双方都准备好后，说说自己在冲突中的部分，并问问对方如何看待。如果谈话再次变得不安全，就停下来并寻求支持。无需一下解决所有分歧。"),
        MiniArticle(ArticleIds.ApologyResponsibility, "道歉不等于放弃界限", "承认行为，并说清会如何改变", "有帮助的道歉要具体：「我打断了你，下次会先听你说完。」别紧接着加「但是你……」。承认自己的错误，不代表必须接受所有指责或放弃安全。"),
        MiniArticle(ArticleIds.FeedbackAsInformation, "把反馈和自我价值分开", "弄清哪些内容可以用", "找出能够改变的具体行为；反馈不清楚时，可以要一个例子。一次结果不能评价完整的你。把侮辱称作批评，也不会让它变成有用的反馈。"),
        MiniArticle(ArticleIds.ReceiveNo, "别人对你说不时", "拒绝一个请求不一定是在拒绝你", "把对具体请求的回答和对自己的判断分开。如果合适，可以问问是否有其他时间或办法。你可以失望，同时也去别处寻找支持。"),
        MiniArticle(ArticleIds.CheckAssumption, "用一个问题核实猜测", "先澄清意思，再编出故事", "如果消息有歧义，可以中性地问：「我理解得对吗，你是说……？」这比回应想象中的弦外之音更有效。如果不能确认，就分清事实和推测，先别下结论。"),
        MiniArticle(ArticleIds.AskSupport, "请求支持是一种能力", "说清什么会有帮助", "你可以请别人听你说、陪你走走，或帮一件具体的事。说明你想要建议还是陪伴。如果对方帮不了，也不代表你的需要过分。"),
        MiniArticle(ArticleIds.SupportWithoutFixing, "陪伴对方，不必解决一切", "询问对方需要哪种支持", "可以问：「你想让我听你说、陪着你，还是一起想下一步？」不要承诺做不到的事。支持既尊重对方的选择，也尊重你的界限。"),
        MiniArticle(ArticleIds.ConflictNotFailure, "有分歧不代表关系一定结束", "留意彼此怎样对待对方", "除了分歧本身，尊重、能否暂停、是否愿意谈影响也很重要。为了「保住关系」而忍受威胁或暴力不是义务；安全优先。"),
        MiniArticle(ArticleIds.MakeExpectationsClear, "提前说清期待", "别等着对方猜", "共同做事前，先说好期限、分工和完成标准，再确认双方理解一致。清楚沟通不能保证意见相同，但能早点发现差异。"),
        MiniArticle(ArticleIds.DigitalBoundaries, "给消息设定界限", "通知不必支配你的一整天", "选好回复时间；如果合适，关掉不重要的提醒。可以告诉亲近的人你通常何时在线。紧急情况则保留一个明确的其他联系方式。"),
        MiniArticle(ArticleIds.FamilyPressure, "家人反复给建议时", "感谢对方，也说明由你决定", "试试：「我知道你担心，我会考虑并自己决定。」如果对话继续，可以重复这句话或换个话题。只有在不会增加风险时才用这种方式。"),
        MiniArticle(ArticleIds.FriendshipInvitation, "轻松地约别人见面", "小邀请更容易接受或拒绝", "具体而不施压地邀请：「周四下班后要不要散步？」也说明改时间或拒绝都可以。对方的回复说明他现在是否有空，不是对你价值的评判。"),
        MiniArticle(ArticleIds.SmallConnection, "小小的联系也算数", "不必一开始就进行深度交流", "感到孤独时，选一种轻松的方式和人接触：发条短消息、去熟悉的地方，或聊些普通话题。够了就停。目标是尝试连接，而不是逼自己马上变得外向。"),

        MiniArticle(ArticleIds.OrientNow, "确认自己此刻在哪里", "温和地回到当下", "看看周围，说出地点、日期或一天中的时段、几个物品，以及正在发生的事。睁着眼睛，按舒服的节奏来。如果焦虑加重，就换成中性的外部物品或寻求支持。"),
        MiniArticle(ArticleIds.GroundingChoice, "选择适合自己的落地练习", "并非每个人都适合关注身体", "可以说出颜色、描述物品、感受椅子的支撑，或听一段稳定的声音。选一个此刻能接受的支点。如果不舒服，就停下来换一种。"),
        MiniArticle(ArticleIds.AfterNightmare, "做了难受的梦之后", "提醒自己梦已经结束", "打开柔和的灯，看看周围，说出几个表明你此刻在房间里的线索。不必详细回忆梦境。如果噩梦反复出现或影响睡眠，可以和医疗专业人士聊聊。"),
        MiniArticle(ArticleIds.AnniversaryReaction, "难熬的日子和纪念日", "反应可能提前出现，也可能晚些出现", "如果某个日期会让你想起困难经历，可以提前减少安排并选择支持。你可以按自己的方式纪念，也可以不纪念。强烈感受不代表又回到了起点。"),
        MiniArticle(ArticleIds.PaceRecovery, "按自己的节奏恢复", "别把自我照顾变成马拉松", "选一个做得到的练习和愿意投入的时间。你可以停下或换方法。除了情绪，也留意自己是否感到更舒服、更安全。"),
        MiniArticle(ArticleIds.SafetyFirst, "安全比练习更重要", "自助不要求你留在危险中", "附近有威胁时，先尽量去更安全的地方，并联系能提供帮助的人。呼吸或落地练习不能替代保护、医疗照护或紧急服务。"),
        MiniArticle(ArticleIds.ChooseTrustedPerson, "选一个可以求助的人", "想想可以简单联系谁", "选一位通常尊重你界限的人。准备一句话：「我现在很难受，你能和我保持联系吗？」如果没有合适的人，可以联系专业人士或当地支持服务。"),
        MiniArticle(ArticleIds.AfterStressRecovery, "经历紧张事件之后", "给自己时间回到日常事情中", "困难的一天之后，选一件基本照料和一件安静活动：吃点东西、换衣服、静坐或联系亲近的人。不必立刻解释全部经过，也不用马上恢复原来的效率。"),
        MiniArticle(ArticleIds.FlashbackGrounding, "感觉过去又回到眼前时", "回到当下，同时保留选择", "看看周围；如果有帮助，说出所在地点和日期。选一个看得见的物品，或联系身边的人。不必强迫自己闭眼、深呼吸或讲细节；有危险时要找现实中的帮助。"),
        MiniArticle(ArticleIds.RecoveryNotLinear, "恢复不是直线前进", "难熬的一天不会抹去已有进展", "别拿自己和完美的上升曲线比较，看看今天什么能帮到你。好了一阵后，强烈感受也可能回来。如果情况变差或难以应对，可以再次寻求支持。"),

        MiniArticle(ArticleIds.BreathIsOptional, "呼吸练习是自愿的", "不要强迫自己改变呼吸", "如果关注呼吸让你不舒服，就让呼吸保持自然，改选外部支点：颜色、声音或物品。呼吸练习并不适合所有人；明显气短或出现新症状时，应寻求医疗帮助。"),
        MiniArticle(ArticleIds.GroundingCanChange, "落地练习没帮助时", "换个方法，或停下来", "练习不必每次都有效。试试更简单的外部支点，请身边的人描述环境，或结束练习。一次不顺利不代表你做错了。"),
        MiniArticle(ArticleIds.MovementAnchor, "用动作作为支点", "小动作可以帮你找回选择感", "如果舒服且安全，可以慢慢张开、握紧双手，或把重心从一只脚移到另一只脚。也可以看一个移动的物体。不要忍痛；如果更合适，就选静止的东西。"),
        MiniArticle(ArticleIds.SensesAnchor, "通过感官找到支点", "选一个中性的环境信号", "说出一种颜色、空气温度或不让你烦躁的稳定声音。不必找五样东西，也不必闭眼。一个中性信号可能就够了；不舒服就换一个。"),
        MiniArticle(ArticleIds.EarlyStressSigns, "留意过载的早期信号", "早点发现会多一些选择", "想想自己最先出现什么变化：说话变快、身体紧绷、注意力下降，或想取消一切。记下这个信号和一种温和回应：暂停、澄清任务或求助。这是观察，不是诊断。"),
        MiniArticle(ArticleIds.RelaxWithoutForce, "不费力地放松", "不必要求自己完全平静", "选一个无需太多专注的动作：放下肩膀、坐舒服些或松开手。呼吸保持自然。稍微舒服一点就够了，不必强迫身体完全放松。"),
        MiniArticle(ArticleIds.BasicCareWithoutRules, "不设严格规则的基本照料", "选一件现在需要的事", "问问自己接下来一小时需要什么：水、食物、温暖、安静、活动或联系。只选目前能做到的。如果做不到，不要责怪自己；可能是缺少支持或合适条件。"),
        MiniArticle(ArticleIds.NewSymptomsCare, "新的或不寻常的症状", "别根据一篇文章给自己下诊断", "身体症状如果是新的、很强烈或变化很快，请联系医疗专业人士。出现紧急情况的征兆时，联系当地急救服务。自助练习不应耽误医疗评估。"),
        MiniArticle(ArticleIds.FindTherapist, "如何寻找专业人士", "寻找合适的合作关系，不必追求完美描述", "询问培训背景、相关经验、形式、费用和保密方式。第一次见面时，可以问工作如何进行、怎样判断是否有帮助。如果不合适，你可以寻找其他专业人士。"),
        MiniArticle(ArticleIds.FirstAppointment, "第一次咨询", "不必准备一段完美的经历叙述", "记下最重要的两件事和关于会谈的问题。可以说「我不太会解释」，再从上周的一个例子开始。你可以要求暂停，或询问哪些内容会保密。"),
        MiniArticle(ArticleIds.DescribeSymptoms, "如何描述自己的状况", "真实例子比完美术语更有用", "说说什么时候开始、多久发生一次，以及日常生活有什么变化。如果难以开口，可以带一张笔记。求助之前不必先猜出诊断。"),
        MiniArticle(ArticleIds.SelfHelpLimits, "自助不够时", "寻求专业支持是合理的下一步", "如果状态长期影响睡眠、工作、学习或自我照料，正在变差，或练习没有帮助，可以联系医疗专业人士或心理咨询师。不必先证明自己已经独自努力够久。"),

        MiniArticle(ArticleIds.ScreeningNotDiagnosis, "问卷不是诊断", "结果可以开启对话，不是给你贴标签", "答案反映特定时期的感受，也会受环境影响。如果结果令你担心，可以和专业人士一起看。不要只凭一个分数改变治疗或做重要决定。"),
        MiniArticle(ArticleIds.SupportPlan, "准备一份简短的支持计划", "记下信号、步骤和联系方式", "写下自己如何发现状况变难、什么通常有帮助，以及可以告诉谁。加上专业人士和当地紧急服务的联系方式。计划不能代替帮助，但能在难以思考时提醒你联系谁。"),
        MiniArticle(ArticleIds.CrisisSteps, "如果你此刻不安全", "联系能够即时回应的人或服务", "如果可能，先去更安全的地方，并联系当地紧急服务或信任的人。简短说明发生了什么、你在哪里。有即时危险时，不要独自留在现场。"),
        MiniArticle(ArticleIds.MedicationWithClinician, "用药问题请咨询专业人士", "不要自行改变处方", "如果担心药物，记下药名、问题和不适反应，再联系开药的专业人士或药师。不要根据文章或应用自行开始、停用或改变剂量。"),
    ];
}
